workedExamples.question_text:
The graph shows straight-line depreciation. Find (a) the annual dollar loss and (b) the value after $4$ years.
[tikz]
\begin{tikzpicture}
\definecolor{blue}{HTML}{268CFF}
\definecolor{housegrid}{HTML}{CCCCCC}
\begin{axis}[width=7cm,height=5.8cm,axis lines=left,axis line style={black,-{Stealth}},xmin=0,xmax=6.5,ymin=0,ymax=20000,xtick={0,1,2,3,4,5,6},ytick={0,3000,6000,9000,12000,15000,18000},grid=major,grid style={color=housegrid,line width=0.25pt},samples=2,clip=false,scaled ticks=false,tick style={black},ticklabel style={text=black,font=\fontsize{8.5}{10}\selectfont,/pgf/number format/fixed},label style={text=black,font=\fontsize{10}{12}\selectfont},xlabel={Years, $n$},ylabel={Value (\$)},ylabel style={at={(axis description cs:-0.32,0.5)},anchor=south}]
\addplot[thick,blue,domain=0:6]{18000-3000*x};
\end{axis}
\end{tikzpicture}
[/tikz]

